 let modalNode=null,modalPlaceholder=null,modalReturnFocus=null;
  function openContent(id,title){const node=$(id);if(!node)return;openModalContent(node,title)}
  function normalizeEditorPane(pane){return ({behavior:'basics',advanced:'scope'})[pane]||pane||'basics'}
  function activateEditorSection(pane,title){const editor=$('aiAgentEditor'),section=normalizeEditorPane(pane);editor.dataset.aiActivePane=section;editor.querySelectorAll('[data-ai-section-nav]').forEach(button=>{const active=button.dataset.aiSectionNav===section;button.classList.toggle('is-active',active);button.setAttribute('aria-selected',String(active));button.tabIndex=active?0:-1;});if(title&&modalNode===editor)$('aiAgentsModalTitle').textContent=title;return section}
  function openEditorPane(pane,title){const editor=$('aiAgentEditor');activateEditorSection(pane,title);if(modalNode===editor)return;openModalContent(editor,title)}
  function showEditorSection(pane){const section=normalizeEditorPane(pane),keys={basics:'behavior',scope:'scope',schedule:'schedule',stopping:'stopping',knowledge:'knowledge',triggers:'triggers',dialogs:'drafts'};openEditorPane(section,t(keys[section]||'editAgent')+(selected?' · '+selected.name:''));if(section==='knowledge')loadKnowledge();if(section==='triggers')loadTriggers();if(section==='dialogs')loadDrafts();}

 function openModalContent(node,title){if(modalNode)closeModal();notice('');const modal=$('aiAgentsModal'),body=$('aiAgentsModalBody');modalReturnFocus=document.activeElement;modalPlaceholder=document.createComment('ai-modal-origin');node.parentNode.insertBefore(modalPlaceholder,node);modalNode=node;node.hidden=false;body.replaceChildren(node);$('aiAgentsModalTitle').textContent=title;modal.hidden=false;document.body.dataset.aiModalOpen='true';$('aiAgentsModalClose').focus();}
 function closeModal(){if(!modalNode)return;const modal=$('aiAgentsModal');modalNode.hidden=true;if(modalNode.id==='aiAgentEditor')delete modalNode.dataset.aiActivePane;if(modalPlaceholder?.parentNode)modalPlaceholder.parentNode.insertBefore(modalNode,modalPlaceholder);modalPlaceholder?.remove();modalPlaceholder=null;modalNode=null;$('aiAgentsModalBody').replaceChildren();modal.hidden=true;delete document.body.dataset.aiModalOpen;modalReturnFocus?.focus?.();modalReturnFocus=null;}
 function renderCompanyStatus(){const host=$('aiStatusSummary');if(!host||!settings)return;const state=settings.runtime||{};host.textContent=[t('companyAI')+': '+t(settings.enabled?'on':'off'),t('companyMode')+': '+(settings.operating_mode==='active'?'Active Mode':'Test Mode')].join(' · ');$('aiKillSwitch').textContent=[t('serverLimits'),'AI: '+t(settings.server_ai_agents_enabled?'on':'off'),t('companyAutoSend')+': '+t(settings.server_auto_send_enabled?'allowed':'denied'),state.staging_mode?'STAGING_MODE':'',state.daily_ai_limit!=null?t('dailyCalls')+': '+state.daily_ai_limit:'',state.platform_token_limit?t('dailyTokens')+': '+state.platform_token_limit:''].filter(Boolean).join(' · ');}

 async function api(path,method='GET',data){const version=aiEpoch,who=profile?.tenant_id+':'+profile?.telegram_id;if(method!=='GET'&&!aiReady)throw new Error(t('loading'));const response=await fetch(endpoint+path,{method,credentials:'same-origin',cache:'no-store',headers:data?{'Content-Type':'application/json'}:{},...(data?{body:JSON.stringify({...data,expected_tenant_id:profile?.tenant_id,expected_user_id:profile?.telegram_id})}:{})});const payload=await response.json().catch(()=>({}));if(!document?.body||version!==aiEpoch||who!==profile?.tenant_id+':'+profile?.telegram_id)throw new Error(t('companyChanged'));if(!response.ok||!payload.success){const error=new Error(payload.error||t('error'));error.status=response.status;throw error;}return payload.result;}

 function notice(message){const modalNotice=$('aiModalNotice');if(modalNotice){modalNotice.textContent=window.tenantI18n?.source(message)||message||'';modalNotice.hidden=!message;}const el=$('aiAgentsNotice');if(el){el.textContent=window.tenantI18n?.source(message)||message||'';el.classList.toggle('show',!!message)}}
 let testSourceChosen=false,testDialogOffset=null,testDialogs=[],testDialogRevision=0;
 function renderTestSource(resetFlags=false){const isConnect=$('aiTestSource').value==='connect',binding=isConnect?testMode?.connect||{}:testMode||{};['aiTestCompanyPhone','aiTestClientPhone','aiTestAccount','aiTestChannel','aiTestLead','aiTestContact','aiTestTalk','aiTestChat','aiCompanyPhoneAttested'].forEach(id=>{const node=$(id)?.closest('label');if(node)node.hidden=isConnect});['aiConnectTestChannel','aiConnectTestConversation','aiConnectTestSearch'].forEach(id=>{const node=$(id)?.closest('label');if(node)node.hidden=!isConnect});$('aiTestModeDiscover').hidden=isConnect;$('aiTestTalkChoices').hidden=isConnect;$('aiTestModeVerify').hidden=isConnect;$('aiConnectTestHelp').hidden=!isConnect;$('aiConnectTestMore').hidden=!isConnect||testDialogOffset===null;if($('aiTestAgent')){const chosen=resetFlags?binding.agent_id||selected?.id||agents[0]?.id:$('aiTestAgent').value;setOptions('aiTestAgent',agents.filter(a=>a.enabled).map(a=>({value:a.id,label:a.name})),[chosen||''],'Выберите агента');}if(resetFlags){$('aiTestModeEnabled').checked=!!binding.enabled;$('aiEmergencyStop').checked=!!binding.emergency_stop;}$('aiTestModeState').textContent=t(binding.emergency_stop?'testStopped':binding.enabled&&binding.verified?'testVerified':'testUnverified')+(isConnect?' '+t('testOnlyDrafts'):'');$('aiTestModeSave').textContent=t('testSave');}
