  function renderAgents(){const host=$('aiAgentList');host.innerHTML=agents.length?agents.map(agent=>`<article class="ai-company-agent"><div><b data-user-content>${esc(agent.name)}</b><small>${t(agent.enabled?'on':'off')} · ${agent.mode==='automatic'?'Automatic':'Manual'} · ${esc(agent.model||'AI')}</small><small>${(agent.scopes||[]).some(scope=>scope.provider==='connect')?'Connect WhatsApp':'Kommo'}</small></div><div><button type="button" class="${agent.enabled?'outline danger':'primary'}" data-toggle-agent="${esc(agent.id)}">${t(agent.enabled?'disableAgent':'enableAgent')}</button><button type="button" class="outline" data-edit-agent="${esc(agent.id)}">${t('editAgent')}</button><button type="button" class="outline danger" data-delete-agent="${esc(agent.id)}">${t('delete')}</button></div></article>`).join(''):`<p>${t('noAgents')}</p>`;host.querySelectorAll('[data-toggle-agent]').forEach(button=>button.onclick=async()=>{const agent=agents.find(item=>item.id===button.dataset.toggleAgent);if(!agent)return;button.disabled=true;try{const saved=await api('agents/'+agent.id,'PATCH',{enabled:!agent.enabled,expected_version:Number(agent.version)});agents=agents.map(item=>item.id===saved.id?saved:item);if(selected?.id===saved.id)selected=saved;renderAgents();notice(`${saved.name}: ${t(saved.enabled?'on':'off')}`)}catch(error){await load();notice(error.message)}});host.querySelectorAll('[data-edit-agent]').forEach(button=>button.onclick=()=>editAgent(agents.find(agent=>agent.id===button.dataset.editAgent)));host.querySelectorAll('[data-delete-agent]').forEach(button=>button.onclick=async()=>{if(!confirm(t('deleteAgent')))return;try{await api('agents/'+button.dataset.deleteAgent,'DELETE',{});await load();}catch(error){notice(error.message);}});}

 function selectValues(id){return [...$(id).selectedOptions].map(option=>option.value)} function enableMultiClick(id){const box=$(id);if(!box||box.dataset.multiClick)return;box.dataset.multiClick='true';box.addEventListener('mousedown',event=>{const option=event.target;if(option?.tagName!=='OPTION')return;event.preventDefault();option.selected=!option.selected;box.dispatchEvent(new Event('change',{bubbles:true}))})}
