  function syncScheduleUi(){const enabled=$('aiScheduleEnabled').checked,fields=$('aiScheduleFields'),status=$('aiScheduleStatus');fields.hidden=!enabled;if(!enabled){status.textContent=t('scheduleAlways');status.dataset.state='good';return;}const zone=$('aiScheduleTimezone').value.trim(),days=[...document.querySelectorAll('[name=aiScheduleDay]:checked')],start=$('aiScheduleStart').value,end=$('aiScheduleEnd').value;if(!zone||!days.length||!start||!end){status.textContent=t('scheduleIncomplete');status.dataset.state='warn';return;}if(end===start){status.textContent=t('scheduleSame');status.dataset.state='warn';return;}status.textContent=t('scheduleValue',{days:days.length,start,end,zone,overnight:end<start?t('nextDay'):''});status.dataset.state='good';}

