 function serializeAgentScopes(provider,channels,stageKeys,existingScopes,allowGroups=false){const scoped=provider==='connect'?channels.map(channel_id=>({provider:'connect',pipeline_id:'',stage_id:'',channel_id,instructions:'',allow_group_messages:allowGroups===true})):stageKeys.flatMap(key=>{const [pipeline_id,stage_id]=key.split('|');return (channels.length?channels:['']).map(channel_id=>({provider:'kommo',pipeline_id,stage_id,channel_id,instructions:''}))});const untouched=(existingScopes||[]).filter(item=>(item.provider||'kommo')!==provider);const preserved=scoped.map(item=>({...item,instructions:(existingScopes||[]).find(old=>(old.provider||'kommo')===item.provider&&String(old.pipeline_id||'')===String(item.pipeline_id||'')&&String(old.stage_id||'')===String(item.stage_id||'')&&String(old.channel_id||'')===String(item.channel_id||''))?.instructions||''}));return preserved.length?[...untouched,...preserved]:(existingScopes||[])}
