 document.querySelector('[data-ai-overview-diagnostics]')?.addEventListener('click',async event=>{
  const button=event.currentTarget;button.disabled=true;button.textContent='Проверяю…';
  try{
   const result=await api('diagnostics?limit=10');
   const has=(object,key)=>Object.prototype.hasOwnProperty.call(object,key);
   const system=result?.system,runtime=result?.runtime,flags=result?.server_flags;
   const valid=result&&typeof result==='object'&&!Array.isArray(result)
    &&system&&typeof system==='object'&&typeof system.tenant_id==='string'&&typeof system.tenant_status==='string'
    &&has(system,'operating_mode')&&typeof system.company_settings_configured==='boolean'
    &&typeof system.company_ai_enabled==='boolean'&&typeof system.emergency_stop==='boolean'
    &&typeof system.auto_send_enabled==='boolean'&&Number.isInteger(system.connected_connect_accounts)
    &&Number.isInteger(system.active_connect_channels)
    &&flags&&typeof flags.ai_agents_enabled==='boolean'&&typeof flags.auto_send_enabled==='boolean'
    &&runtime&&typeof runtime==='object'&&typeof runtime.configured_ai_agents_enabled==='boolean'
    &&typeof runtime.configured_auto_send_enabled==='boolean'&&typeof runtime.staging_mode==='boolean'
    &&typeof runtime.service_id==='string'&&typeof runtime.deployment_id==='string'
    &&Array.isArray(result.channels)&&Array.isArray(result.agents)&&Array.isArray(result.events)
    &&typeof result.latest_event_found==='boolean';
   if(!valid){const error=new Error('Сервер вернул неполный ответ диагностики; состояния не показаны.');error.status=200;throw error;}
   const latest=result.events[0],state=system;
   const details=[`Tenant: ${state.tenant_id||'не определён'}`];
   if(runtime.service_name||runtime.service_id)details.push(`Процесс: ${runtime.service_name||'worker'} (${runtime.service_id||'ID не передан'})`);
   if(runtime.deployment_id)details.push(`Deployment: ${runtime.deployment_id}`);
   if(runtime.environment_name||runtime.environment_id)details.push(`Окружение: ${runtime.environment_name||''} ${runtime.environment_id||''}`.trim());
   details.push(`Флаги процесса (Railway env → действует): AI_AGENTS_ENABLED=${runtime.configured_ai_agents_enabled?'true':'false'} → ${flags.ai_agents_enabled?'true':'false'}, AI_AGENTS_AUTO_SEND_ENABLED=${runtime.configured_auto_send_enabled?'true':'false'} → ${flags.auto_send_enabled?'true':'false'}${runtime.staging_mode?' (STAGING_MODE=true)':''}`);
   details.push(`AI компании: ${state.company_ai_enabled?'включён':'выключен'}; режим: ${state.company_settings_configured?(state.operating_mode==='active'?'Active Mode':state.operating_mode==='test'?'Test Mode':state.operating_mode||'не указан'):'настройки компании ещё не созданы'}`);
   details.push(`Автоотправка компании/сервера: ${state.auto_send_enabled?'разрешена':'запрещена'}/${flags.auto_send_enabled?'разрешена':'запрещена'}`);
   details.push(`Connect: ${state.connected_connect_accounts||0} подключений, ${state.active_connect_channels||0} активных каналов${(result.channels||[]).length?` (${result.channels.map(channel=>`${channel.name||'WhatsApp'} ${channel.channel_id}${channel.active?'':' — неактивен'}`).join(', ')})`:''}`);
   if(profile?.tenant_id&&state.tenant_id&&String(profile.tenant_id)!==String(state.tenant_id))details.push('Ошибка: настройки и диагностика открыты для разных компаний. Перезагрузите кабинет и выберите одну компанию.');
   if(!flags.ai_agents_enabled)details.push('Блокировка: на Railway в сервисе worker включите AI_AGENTS_ENABLED=true, затем дождитесь нового deployment.');
   if(!state.company_settings_configured||!state.company_ai_enabled)details.push('Блокировка компании: в AI Agents → Настройки включите «AI Agents активен для компании» и сохраните.');
   if(!state.active_connect_channels)details.push('Канал не привязан к этой компании: откройте Tənzimləmələr → Connect WhatsApp, подключите Connect и выберите канал для этой компании.');
   const linkedChannelIds=new Set((result.channels||[]).filter(channel=>channel.active).map(channel=>String(channel.channel_id)));
   const matchingAgents=(result.agents||[]).filter(agent=>agent.enabled&&(agent.connect_scope_channel_ids||[]).some(id=>!id||linkedChannelIds.has(String(id))));
   if((result.agents||[]).length)details.push(`Агенты: ${result.agents.map(agent=>`${agent.name||agent.agent_id}: ${agent.enabled?'включён':'выключен'}, ${agent.mode||'режим не задан'}, Connect scope ${(agent.connect_scope_channel_ids||[]).join(', ')||'не задан'}`).join('; ')}`);
   if(state.active_connect_channels&&!matchingAgents.length)details.push('Нет включённого агента с Connect scope для привязанного канала. В редакторе агента выберите точный WhatsApp-канал и сохраните.');
   if(runtime.configured_auto_send_enabled&&!flags.auto_send_enabled&&runtime.staging_mode)details.push('Переменная автоотправки задана, но runtime блокирует её в режиме STAGING_MODE. Проверьте, что production-сервис worker не запущен как staging.');
   if(!latest){details.push('Входящих событий Connect в Beintaskbot нет. Регистрация канала сама по себе не подтверждает доставку webhook: проверьте доставку событий на стороне Connect.');notice(details.join(' · '));return;}
   details.push(`Последнее событие: ${latest.received_at||'время неизвестно'}`,`состояние webhook: ${latest.event_state||'неизвестно'}`);
   if(latest.event_error)details.push(`webhook: ${latest.event_error}`);
   details.push(`агент: ${latest.agent_name||'не выбран'}`);
   if(latest.job_state)details.push(`AI-задача: ${latest.job_state}`);
   if(latest.job_error)details.push(`причина: ${latest.job_error}`);
   if(latest.run_state)details.push(`модель: ${latest.run_state}`);
   if(latest.auto_send_block_reason)details.push(`отправка: ${latest.auto_send_block_reason}`);
   notice(details.join(' · '));
  }catch(error){const status=Number.isInteger(error.status)?` (HTTP ${error.status})`:'';notice(`Не удалось получить диагностику${status}: ${error.message||'проверьте соединение с сервером'}`)}
  finally{button.disabled=false;button.textContent=t('diagnostics')}
 });
 function dialogStateMeta(value){const state=String(value||'').toLowerCase();if(state==='active')return{state,label:'AI активен'};if(state==='paused')return{state,label:'AI приостановлен'};if(state==='human')return{state,label:'Передан человеку'};if(state==='blocked')return{state,label:'AI заблокирован'};return{state:'blocked',label:'AI заблокирован'}}
 function dialogReason(value){const code=String(value||'').trim(),labels={manager_replied:'Сотрудник ответил вручную',manager_pause:'Сотрудник приостановил AI',human_handoff:'Сотрудник передал диалог человеку',customer_requested_manager:'Клиент запросил сотрудника',trigger_reply_sent_then_handoff:'После ответа AI диалог передан человеку',server_ai_disabled:'AI отключён на сервере',company_ai_disabled:'AI отключён для компании',emergency_stop:'Включена аварийная остановка',tenant_ai_unavailable:'AI недоступен для компании',agent_not_found:'Для диалога не найден агент',agent_disabled:'Агент отключён',ai_emergency_stop:'Включена аварийная остановка',connect_admission_blocked:'Канал или Test Mode не разрешает работу AI',ai_agents_server_disabled:'AI отключён на сервере',conversation_human_or_paused:'Диалог уже остановлен для человека или паузы',newer_inbound:'Получено более новое сообщение клиента'};return labels[code]||code}
 function dialogTime(value){if(!value)return'';const parsed=new Date(value);return Number.isNaN(parsed.getTime())?String(value):parsed.toLocaleString()}
 async function openAiDialog(row){const lead=String(row.lead_id||'').trim(),opener=window.openInboxChat||window.openDealViewById||window.openNoticeClient;if(!lead||typeof opener!=='function'){notice('Переписка пока недоступна для открытия в этом интерфейсе.');return}closeModal();await opener(lead)}
